sp_ListarCliente	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarCliente`()\nBEGIN\n    SELECT\n        c.idCliente,\n        c.idEmpresa,\n        c.Nome        AS nome,\n        c.nomeFantasia,\n        c.razaoSocial,\n        c.CNPJ_CPF    AS cpfCNPJ,\n        c.Email       AS email,\n        c.Telefone    AS telefone,\n        c.tipoCliente_id,\n        c.Observacao  AS observacao,\n        c.Genero      AS genero,\n        c.saldoDevedor,\n        c.enderecoId,\n        c.dthCadastro,\n        c.dthNascimento,\n        c.fAtivo,\n        e.tipoEndereco,\n        e.Logradouro  AS logradouro,\n        e.Numero      AS numero,\n        e.Complemento AS complemento,\n        e.Bairro      AS bairro,\n        e.Cidade      AS cidade,\n        e.Estado      AS estado,\n        e.Pais        AS pais,\n        e.CEP         AS cep\n    FROM Cliente c\n    LEFT JOIN Endereco e ON e.idEndereco = c.enderecoId;\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
